from itertools import product

# 元素: e, x2, x3, x1 -> 用索引 0,1,2,3
# 乘法表 (行 * 列):
#   * |   e  x2  x3  x1
#   e |   e  x2  x3  x1
#  x2 |  x2  x3  x1   e
#  x3 |  x3  x1   e  x2
#  x1 |  x1   e  x2  x3

table = [
    [0, 1, 2, 3],  # e
    [1, 2, 3, 0],  # x2
    [2, 3, 0, 1],  # x3
    [3, 0, 1, 2],  # x1
]
names = ['e', 'x2', 'x3', 'x1']

# 验证群的公理 + 计算每个元素的阶
def power(a, n):
    result = 0  # e
    for _ in range(n):
        result = table[result][a]
    return result

print("各元素的阶:")
for a in range(4):
    for n in range(1, 5):
        if power(a, n) == 0:
            print(f"  {names[a]}: order = {n}")
            break

# 枚举所有子集，检查是否为子群
from itertools import combinations

def is_subgroup(subset):
    s = set(subset)
    if 0 not in s:  # 必须含单位元
        return False
    # 闭合性
    for a in subset:
        for b in subset:
            if table[a][b] not in s:
                return False
    # 逆元
    for a in subset:
        found = False
        for b in subset:
            if table[a][b] == 0:
                found = True
                break
        if not found:
            return False
    return True

print("\n所有子群:")
for r in range(1, 5):
    for combo in combinations(range(4), r):
        if is_subgroup(combo):
            print(f"  {{{', '.join(names[i] for i in combo)}}}")
